def tag(t):
    def deco(fn):
        return lambda: f'<{t}>' + fn() + f'</{t}>'
    return deco
@tag('b')
@tag('i')
def hi(): return 'hi'
print(hi())

class A:
    def who(self): return 'A'
class B(A):
    def who(self): return 'B' + super().who()
class C(A):
    def who(self): return 'C' + super().who()
class D(B, C):
    def who(self): return 'D' + super().who()
print(D().who())

