import asyncio
for exc in (ValueError, KeyboardInterrupt, asyncio.CancelledError, SystemExit):
    try:
        try:
            raise exc()
        except Exception:
            print(exc.__name__, 'caught by except Exception')
    except BaseException:
        print(exc.__name__, 'NOT caught by except Exception')

